type UpsertCatalogLimitParams struct {
	MerchantID    uuid.UUID
	LimitKey      string
	Unit          string
	ResetKind     string
	WindowSeconds *int32
	ResetAnchor   *string
	Overrun       string
	RateCards     []byte
}

func (q *Queries) UpsertCatalogLimit(ctx context.Context, arg UpsertCatalogLimitParams) error {
	_, err := q.db.Exec(ctx, upsertCatalogLimit,
		arg.MerchantID,
		arg.LimitKey,
		arg.Unit,
		arg.ResetKind,
		arg.WindowSeconds,
		arg.ResetAnchor,
		arg.Overrun,
		arg.RateCards,
	)
	return err
}

